import numpy as np
import numba
import sys, signal

gen = np.random.default_rng(0)

@numba.njit
def foo(g):
    return g.binomial(700, 0.1, 100)

class Timeout(Exception):
    pass

def handler(signum, frame):
    raise Timeout()

signal.signal(signal.SIGALRM, handler)
signal.alarm(5)
try:
    out = foo(gen)
    signal.alarm(0)
    print('COMPLETED', np.asarray(out).shape, float(np.asarray(out).sum()))
except Timeout:
    print('HANG_TIMEOUT')
except Exception as e:
    print('EXCEPTION', type(e).__name__, str(e)[:200])
finally:
    signal.alarm(0)
PY
